TARGET INVENTORY

{
  "targetFolder": "/workspaces/MetrAIyux-0S/SkyeGateFS27",
  "htmlFiles": 28,
  "cssFiles": 7,
  "jsFiles": 271
}

MCP MANAGED CSS IMPLEMENTATION



MCP MANAGED JS IMPLEMENTATION



CSS IMPLEMENTATION SIGNALS

:root {
  --sky-bg: #07080c;
  --sky-panel: rgba(13, 16, 24, 0.86);
  --sky-panel-2: rgba(22, 24, 32, 0.72);
  --sky-line: rgba(255, 255, 255, 0.14);
  --sky-text: rgba(255, 255, 255, 0.94);
  --sky-muted: rgba(255, 255, 255, 0.68);
  --sky-soft: rgba(255, 255, 255, 0.48);
  --sky-gold: #f6c14b;
  --sky-cyan: #27f2ff;
  --sky-rose: #ff5f8f;
  --sky-green: #74f2a7;
  --sky-purple: #8a4fff;
  --sky-shadow: 0 22px 70px rgba(0, 0, 0, 0.46);
  --sky-sans: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; }
html { min-height: 100%; background: var(--sky-bg); }
body {
  min-height: 100%;
  margin: 0;
  color: var(--sky-text);
  font-family: var(--sky-sans);
  background:
    linear-gradient(115deg, rgba(7, 8, 12, 0.98), rgba(14, 14, 20, 0.94) 44%, rgba(6, 12, 14, 0.98)),
    repeating-linear-gradient(90deg, rgba(255,255,255,0.04) 0 1px, transparent 1px 92px),
    repeating-linear-gradient(0deg, rgba(255,255,255,0.035) 0 1px, transparent 1px 92px);
  overflow-x: hidden;
}

body,
.hero-copy,
.checkout-console,
.usage-band,
.gate-path {
  opacity: 1;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(140deg, rgba(246, 193, 75, 0.08), transparent 32%),
    linear-gradient(300deg, rgba(39, 242, 255, 0.08), transparent 38%),
    linear-gradient(20deg, transparent, rgba(255, 95, 143, 0.06) 62%, transparent 88%);
  z-index: -2;
}

.motion-progress {
  position: fixed;
  inset: 0 0 auto 0;
  height: 4px;
  z-index: 100;
  background: rgba(255,255,255,0.06);
}
.motion-progress span {
  display: block;
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, var(--sky-gold), var(--sky-cyan), var(--sky-rose));
  box-shadow: 0 0 24px rgba(39, 242, 255, 0.52);
}

.cursor-glow {
  position: fixed;
  left: 0;
  top: 0;
  width: 220px;
  height: 220px;
  pointer-events: none;
  transform: translate3d(-50%, -50%, 0);
  background: radial-gradient(circle, rgba(39, 242, 255, 0.15), rgba(246, 193, 75, 0.08) 32%, transparent 66%);
  mix-blend-mode: screen;
  z-index: 2;
}

.scanline {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  background: linear-gradient(180deg, transparent, rgba(255,255,255,0.035), transparent);
  height: 180px;
  animation: scan 8s linear infinite;
}

@keyframes scan {
  0% { transform: translateY(-200px); }
  100% { transform: translateY(calc(100vh + 200px)); }
}

::-webkit-scrollbar { width: 14px; }
::-webkit-scrollbar-track {
  background: rgba(255,255,255,0.075);
  border-left: 1px solid rgba(39, 242, 255, 0.18);
  box-shadow: inset 0 0 16px rgba(39, 242, 255, 0.14);
}
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, var(--sky-cyan), var(--sky-gold), var(--sky-rose));
  border: 3px solid rgba(7,8,12,0.92);
  border-radius: 999px;
  box-shadow: 0 0 18px rgba(39, 242, 255, 0.5);
}

a { color: inherit; }
.pay-nav {
  position: sticky;
  top: 4px;
  z-index: 50;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  width: min(1180px, calc(100% - 28px));
  margin: 14px auto 0;
  padding: 10px 12px;
  border: 1px solid var(--sky-line);
  background: rgba(7, 8, 12, 0.76);
  backdrop-filter: blur(16px);
  box-shadow: var(--sky-shadow);
}

.pay-brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  font-weight: 900;
}
.pay-brand img {
  width: 42px;
  height: 42px;
  object-fit: contain;
}
.pay-brand span {
  font-size: 15px;
  letter-spacing: 0;
}
.pay-nav nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}
.pay-nav nav a {
  padding: 8px 10px;
  border: 1px solid transparent;
  text-decoration: none;
  color: var(--sky-muted);
  font-size: 13px;
}
.pay-nav nav a:hover {
  color: var(--sky-text);
  border-color: var(--sky-line);
}

main {
  width: min(1180px, calc(100% - 28px));
  margin: 0 auto;
  position: relative;
  z-index: 3;
}

.pay-hero {
  min-height: calc(100vh - 82px);
  display: grid;
  grid-template-columns: minmax(0, 1.04fr) minmax(340px, 0.96fr);
  gap: 22px;
  align-items: center;
  padding: 44px 0 32px;
}

.hero-copy {
  max-width: 720px;
}
.eyebrow {
  margin: 0 0 10px;
  color: var(--sky-cyan);
  font-size: 12px;
  text-transform: uppercase;
  font-weight: 900;
  letter-spacing: 0;
}
h1, h2, h3, p { letter-spacing: 0; }
h1 {
  margin: 0;
  font-size: clamp(42px, 6vw, 84px);
  line-height: 0.94;
  font-weight: 950;
  max-width: 650px;
  overflow-wrap: normal;
  color: var(--sky-text);
}
.neon-gradient-text {
  color: transparent;
  background: linear-gradient(90deg, var(--sky-gold), var(--sky-cyan), var(--sky-rose));
  background-size: 220% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 18px rgba(39, 242, 255, 0.14));
  animation: skypayTextShimmer 5.4s ease-in-out infinite alternate;
}
.text-effects {
  position: relative;
  isolation: isolate;
  text-shadow: 0 0 24px rgba(39, 242, 255, 0.16);
}
.text-effects::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -0.08em;
  height: 0.07em;
  transform-origin: left center;
  background: linear-gradient(90deg, rgba(246,193,75,0), rgba(246,193,75,0.9), rgba(39,242,255,0.86), rgba(255,95,143,0));
  filter: blur(0.5px);
  animation: textEffectUnderline 4.8s ease-in-out infinite;
}

@keyframes skypayTextShimmer {
  0% { background-position: 0% 50%; filter: drop-shadow(0 0 12px rgba(246, 193, 75, 0.12)); }
  100% { background-position: 100% 50%; filter: drop-shadow(0 0 24px rgba(39, 242, 255, 0.2)); }
}
@keyframes textEffectUnderline {
  0%, 100% { transform: scaleX(0.28); opacity: 0.52; }
  48% { transform: scaleX(1); opacity: 0.95; }
}
h2 {
  margin: 0;
  font-size: clamp(24px, 4vw, 48px);
  line-height: 1.02;
}
h3 {
  margin: 0;
  font-size: 17px;
}
.lead {
  max-width: 680px;
  color: rgba(255, 255, 255, 0.76);
  font-size: clamp(16px, 2.1vw, 20px);
  line-height: 1.55;
}
.hero-points {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 22px;
}
.hero-points span,
.live-badge,
.mini-label {
  border: 1px solid var(--sky-line);
  background: rgba(255,255,255,0.055);
  padding: 7px 9px;
  font-size: 12px;
  color: var(--sky-muted);
}

.checkout-console,
.usage-band,
.gate-path,
.ledger-login,
.ledger-panel {
  border: 1px solid var(--sky-line);
  background: var(--sky-panel);
  box-shadow: var(--sky-shadow);
  backdrop-filter: blur(20px);
}
.checkout-console {
  padding: 18px;
}
.console-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
}
.console-head h2 {
  font-size: clamp(24px, 3vw, 34px);
}
.live-badge {
  color: var(--sky-green);
  white-space: nowrap;
}
.client-strip,
.ledger-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 14px 0;
}
.client-strip > div,
.ledger-stats > div {
  border: 1px solid rgba(255,255,255,0.12);
  background: rgba(255,255,255,0.045);
  padding: 12px;
  min-width: 0;
}
.mini-label,
.ledger-stats span {
  display: block;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--sky-soft);
  margin-bottom: 7px;
}
.client-strip strong,
.ledger-stats strong {
  display: block;
  overflow-wrap: anywhere;
}

.client-contact {
  margin-top: 12px;
  border: 1px solid rgba(39, 242, 255, 0.2);
  background: rgba(39, 242, 255, 0.055);
  padding: 12px;
}
.client-contact div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.client-contact a {
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(0,0,0,0.2);
  color: var(--sky-text);
  padding: 7px 9px;
  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
}

.pay-form {
  display: grid;
  gap: 12px;
}
label {
  display: grid;
  gap: 7px;
  color: var(--sky-muted);
  font-size: 13px;
  font-weight: 700;
}
input,
select {
  width: 100%;
  border: 1px solid rgba(255,255,255,0.16);
  background: rgba(0,0,0,0.26);
  color: var(--sky-text);
  padding: 12px;
  font: inherit;
  outline: none;
}
input:focus,
select:focus {
  border-color: rgba(39, 242, 255, 0.68);
  box-shadow: 0 0 0 3px rgba(39, 242, 255, 0.12);
}
.skyemerit-panel {
  display: grid;
  gap: 8px;
  border: 1px solid rgba(246, 193, 75, 0.26);
  background: rgba(246, 193, 75, 0.065);
  padding: 12px;
}
.skyemerit-panel p {
  margin: 0;
  color: var(--sky-muted);
  font-size: 12.5px;
  line-height: 1.45;
}
.skyemerit-panel strong {
  color: var(--sky-gold);
}
.offer-select {
  display: grid;
  gap: 8px;
  margin: 2px 0;
}
.offer-option {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  align-items: center;
  border: 1px solid rgba(255,255,255,0.13);
  background: var(--sky-panel-2);
  padding: 12px;
  text-align: left;
  color: var(--sky-text);
  cursor: pointer;
}
.offer-option[aria-pressed="true"] {
  border-color: rgba(246, 193, 75, 0.78);
  box-shadow: 0 0 0 2px rgba(246, 193, 75, 0.12);
}
.offer-option p {
  margin: 4px 0 0;
  color: var(--sky-muted);
  font-size: 13px;
  line-height: 1.35;
}
.bob-offer-summary {
  margin: 4px 0;
}
.bob-trial-card {
  border: 1px solid rgba(246, 193, 75, 0.32);
  background: rgba(246, 193, 75, 0.07);
  padding: 14px;
}
.bob-trial-card strong {
  display: block;
  color: var(--sky-text);
  font-size: 18px;
}
.bob-trial-card p {
  color: var(--sky-muted);
  line-height: 1.45;
  margin: 8px 0 0;
}
.offer-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 8px;
}
.offer-meta em,
.selected-policy span {
  border: 1px solid rgba(39, 242, 255, 0.28);
  background: rgba(39, 242, 255, 0.075);
  color: rgba(230, 252, 255, 0.82);
  font-size: 11px;
  font-style: normal;
  font-weight: 800;
  padding: 4px 6px;
}
.offer-price {
  color: var(--sky-gold);
  font-weight: 900;
  text-align: right;
  white-space: nowrap;
}

.primary-action,
.secondary-action {
  border: 1px solid rgba(255,255,255,0.18);
  color: #05060a;
  cursor: pointer;
  font-weight: 950;
  padding: 12px 14px;
  background: linear-gradient(90deg, var(--sky-gold), var(--sky-cyan));
  min-height: 46px;
}
.secondary-action {
  background: rgba(255,255,255,0.08);
  color: var(--sky-text);
}
.primary-action[disabled] {
  opacity: 0.64;
  cursor: wait;
}
.fine-print {
  color: var(--sky-soft);
  font-size: 12.5px;
  line-height: 1.45;
  margin: 0;
}
.status-panel {
  margin-top: 12px;
  border: 1px solid rgba(116, 242, 167, 0.38);
  background: rgba(116, 242, 167, 0.07);
  padding: 12px;
}
.status-panel h3 {
  color: var(--sky-green);
  margin-bottom: 4px;
}
.status-panel p:last-child {
  color: var(--sky-muted);
  margin: 0;
}

.store-shell {
  padding-bottom: 84px;
}
.store-hero {
  min-height: calc(100vh - 82px);
  display: grid;
  grid-template-columns: minmax(0, 1.04fr) minmax(320px, 0.86fr);
  gap: 22px;
  align-items: center;
  padding: 44px 0 30px;
}
.store-hero-copy {
  max-width: 780px;
}
.store-command-panel,
.store-band,
.store-catalog {
  border: 1px solid var(--sky-line);
  background: var(--sky-panel);
  box-shadow: var(--sky-shadow);
  backdrop-filter: blur(20px);
}
.store-command-panel {
  padding: 18px;
}
.store-command-panel h2 {
  font-size: clamp(24px, 3vw, 34px);
}
#selectedOfferSummary {
  color: var(--sky-muted);
  line-height: 1.5;
}
.selected-policy {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 10px 0 14px;
}
.compact-form {
  gap: 10px;
}
.store-band {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: 18px;
  align-items: start;
  padding: 24px;
  margin: 22px 0;
}
.store-band p:last-child {
  color: var(--sky-muted);
  line-height: 1.55;
}
.store-catalog {
  padding: 24px;
  margin: 22px 0;
}
.catalog-head,
.store-group-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}
.store-group {
  margin-top: 24px;
}
.store-group-head span {
  color: var(--sky-soft);
  font-size: 12px;
  font-weight: 800;
}
.store-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 12px;
}
.store-card {
  min-height: 214px;
  border: 1px solid rgba(255,255,255,0.13);
  background: rgba(11, 14, 20, 0.72);
  color: var(--sky-text);
  cursor: pointer;
  display: grid;
  align-content: space-between;
  gap: 14px;
  padding: 14px;
  text-align: left;
}
.store-card[aria-pressed="true"] {
  border-color: rgba(246, 193, 75, 0.84);
  box-shadow: 0 0 0 2px rgba(246, 193, 75, 0.12), 0 18px 54px rgba(0,0,0,0.24);
}
.store-card-top {
  display: grid;
  gap: 8px;
}
.store-card-top strong {
  font-size: 17px;
  line-height: 1.15;
}
.store-card-top em {
  color: var(--sky-gold);
