@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }
  .cursor-glow,
  .scanline {
    display: none;
  }
}

/* SkyePay gateway redesign: scoped so Store/Admin/API pages keep their existing layout. */
body.skypay-gateway-v2 {
  --pay-ink: #f7f4ea;
  --pay-muted: rgba(247, 244, 234, 0.72);
  --pay-dim: rgba(247, 244, 234, 0.5);
  --pay-line: rgba(247, 244, 234, 0.16);
  --pay-black: #050507;
  --pay-panel: rgba(10, 12, 13, 0.84);
