  --pay-gold: #f1bd4a;
  --pay-cyan: #3be7ff;
  --pay-green: #80e5a2;
  --pay-rose: #ff6f91;
  --pay-graph: rgba(247, 244, 234, 0.055);
  color: var(--pay-ink);
  background:
    linear-gradient(90deg, rgba(241, 189, 74, 0.12), transparent 18%, transparent 82%, rgba(59, 231, 255, 0.1)),
