      : state.client.special_offer || "Free preview first. Confirmed Stripe payment waits for owner-approved activation.";
    $("#includedUsage").innerHTML = (state.client.included_usage || []).map((item) => `<li>${escapeHtml(item)}</li>`).join("");
    renderContact();
