  function renderContact() {
    const contact = state.client?.contact || {};
    const panel = $("#clientContact");
    if (!panel) return;
    if (!contact.email && !contact.phone && !contact.contact_url) {
      panel.hidden = true;
      return;
    }
    panel.hidden = false;
    panel.innerHTML = `
